mapper.select:
select mtl.Met_Name as metName,
c1.C_Name as brandSupplierName,
c2.C_Name as brandProducerName,
apl.Bla_Code as blaCode,
apl.Bla_Title as blaTitle,
mn.*
from Me_BrandLibrary mn
left join Me_Type_Library mtl on mtl.Met_Id = mn.Met_Id
left join Sys_Company c1 on c1.C_Id=mn.Brand_Supplier
left join Sys_Company c2 on c2.C_Id=mn.Brand_Producer
left join Me_BrandLibrary_Apply apl on apl.Bla_Id=mn.Bla_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.state=#{params.state}


    and mn.Brand_Enable=#{params.brandEnable}


    and mn.Brand_Level=#{params.brandLevel}


    and mn.Met_Id=#{params.metId}


    and INSTR(mn.Brand_Name,#{params.brandName})


    and INSTR(mn.Brand_Code,#{params.brandCode})


    and INSTR(mn.Create_Uname,#{params.createUname})


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
